scriptdefs
= LilycoveCity_CoveLilyMotel_2F_EventScript_Scott
lock
faceplayer
goto_if_set FLAG_MET_SCOTT_IN_LILYCOVE LilycoveCity_CoveLilyMotel_2F_EventScript_MetScott
msgbox	SCOTT: … … … … … … … … … … Zzz…… … … … … Häh?! Oh, sorry, sorry! Ich bin eingenickt!Ich bin hergekommen, um mir diese POKéMON-CONTEST-Sache anzuschauen.Ich muss zugeben, sie sieht ziemlich unterhaltsam aus, aber…Nenn mich einen Puristen--ich bevorzuge Kämpfe und starke TRAINER.Aber das bin nur ich.PLAYER, ich hoffe, du genießt alles, die ARENEN, CONTESTS, das BATTLE TENT, das ganze Programm!
addvar VAR_SCOTT_STATE 1
setflag FLAG_MET_SCOTT_IN_LILYCOVE
release
end
= LilycoveCity_CoveLilyMotel_2F_EventScript_MetScott
msgbox	SCOTT: Ich glaube, man braucht schon Strategie, um einen CONTEST zu gewinnen.Sich CONTEST-Strategien auszudenken ist, würde ich sagen, ein Weg, ein besserer TRAINER zu werden.
release
end
= LilycoveCity_CoveLilyMotel_2F_EventScript_Woman
msgbox	Die Meeresbrise kitzelt mein Herz. Es fühlt sich wunderbar hier an!
end
= LilycoveCity_CoveLilyMotel_2F_EventScript_GameBoyKid
msgbox	Man weiß nie, wann und wo einen jemand herausfordert.Deshalb verlasse ich nie ohne meinen GAME BOY ADVANCE das Haus.
end
= LilycoveCity_CoveLilyMotel_2F_EventScript_Programmer
msgbox	Ich? Du redest mit mir? Ich bin der PROGRAMMIERER.Ich frage mich, wie die SPIELAUTOMATEN hier so sind.
end
= LilycoveCity_CoveLilyMotel_2F_EventScript_FatMan
msgbox	Die TUBER-Mädchen sind niedlich, oder? Gegen eine niedliche TUBER zu kämpfen…Juhu, das ist so genial!Und die ZWILLINGE! Sind sie nicht niedlich? Ein 2-gegen-2-Kampf mit den ZWILLINGEN…Juhu, das macht unbeschreiblich viel Spaß!
end
= LilycoveCity_CoveLilyMotel_2F_EventScript_GraphicArtist
msgbox	Ich bin der GRAFIKKÜNSTLER! Sind die POKéMON von HOENN nicht interessant?
end
= LilycoveCity_CoveLilyMotel_2F_EventScript_GameDesigner
lock
faceplayer
call_if_unset FLAG_TEMP_2 LilycoveCity_CoveLilyMotel_2F_EventScript_ShowMeCompletedDex
call_if_set FLAG_TEMP_2 LilycoveCity_CoveLilyMotel_2F_EventScript_ShowDiploma
specialvar VAR_RESULT HasAllHoennMons
goto_if_eq VAR_RESULT TRUE LilycoveCity_CoveLilyMotel_2F_EventScript_AllHoennMonsFanfare
release
end
= LilycoveCity_CoveLilyMotel_2F_EventScript_AllHoennMonsFanfare
setflag FLAG_TEMP_2
playfanfare MUS_OBTAIN_ITEM
waitfanfare
goto LilycoveCity_CoveLilyMotel_2F_EventScript_ShowDiploma
end
= LilycoveCity_CoveLilyMotel_2F_EventScript_ShowDiploma
msgbox	Wow! Das ist genial! Ja, das ist absolut genial!Dieser POKéDEX ist komplett gefüllt! Du musst POKéMON wirklich lieben!Ich bin so beeindruckt!Lass mich dir zur Anerkennung deiner Leistung etwas geben!
waitmessage
call Common_EventScript_PlayGymBadgeFanfare
special Special_ShowDiploma
release
end
= LilycoveCity_CoveLilyMotel_2F_EventScript_ShowMeCompletedDex
msgbox	Ich bin der GAME DESIGNER.Oh, ist das wahr? Du arbeitest an einem POKéDEX?Es ist hart, ihn zu vervollständigen, aber gib nicht auf.Wenn du ihn fertigstellst, komm bitte vorbei und zeig ihn mir.
return
